script:
(function () {
  'use strict';
  // Fixed-rate mortgage vs interest-only mortgage, cash flow and equity, with the savings invested.
  //   Fixed: M = B * i / (1 - (1 + i)^-n), i = rate / 12 (M = B / n at 0%).
  //   Interest-only: B * i each month for the IO period, then the full balance is amortized over the
  //   months left at the same rate. Both households spend the same each month, the larger of the two
  //   payments; whoever pays less invests the difference at month end, growing at (1 + r)^(1/12) - 1.
  //   Home value grows at the appreciation rate, compounded yearly.
  //   Equity = home value - loan balance. Net worth = equity + investments after tax on the gains
  //   (taken as if sold at the horizon). Break-even return: bisection between -20% and 50%.
  // Verified in Node (scratchpad mtg6/tests/fvi.test.js): $400,000 fixed at 6.5% for 30 years =
  //   $2,528.27 and its balance after 120 payments $339,104.51 (closed form); IO at 6.75% = $2,250.00,
  //   then $3,041.46 over the last 20 years (closed form on $400,000); the IO side fund of
  //   $278.27/mo for 10 years at 7% = $47,598.92 (annuity formula); 0% IO rate -> $0 then $1,666.67;
  //   equal rates and a return equal to the loans' effective annual rate -> difference $0.00 at
  //   year 30; blank, negative and out-of-range inputs show an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var cents = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  // --- pure ---
  function payment(balance, annualPct, months) {
    if (months <= 0 || balance <= 0) return 0;
    var i = annualPct / 1200;
    if (i === 0) return balance / months;
    return balance * i / (1 - Math.pow(1 + i, -months));
  }

  // o: loan, years (term), rf, rio (annual %), ioYears, home, appr (%), ret (%), horizon, tax (%)
  function compare(o) {
    var n = o.years * 12, ioN = o.ioYears * 12;
    var pf = payment(o.loan, o.rf, n), ioPay = o.loan * o.rio / 1200, amPay = payment(o.loan, o.rio, n - ioN);
    var g = Math.pow(1 + o.ret / 100, 1 / 12) - 1;
    var bf = o.loan, bi = o.loan, ff = 0, fi = 0, cf = 0, ci = 0, intF = 0, intI = 0, payF = 0, payI = 0, rows = [];
    var yF = 0, yI = 0;
    function after(f, c) { var gain = f - c; return gain > 0 ? f - gain * o.tax / 100 : f; }
    for (var m = 1; m <= o.horizon * 12; m++) {
      var a = 0, b = 0;
      if (bf > 0.005) { var i1 = bf * o.rf / 1200; a = Math.min(pf, bf + i1); bf = bf + i1 - a; intF += i1; } else bf = 0;
      if (bi > 0.005) {
        var i2 = bi * o.rio / 1200;
        b = m <= ioN ? i2 : Math.min(amPay, bi + i2);
        bi = bi + i2 - b; intI += i2;
      } else bi = 0;
      if (Math.abs(bf) < 0.005) bf = 0;
      if (Math.abs(bi) < 0.005) bi = 0;
      var spend = Math.max(a, b);
      var dF = spend - a, dI = spend - b;
      ff = ff * (1 + g) + dF; cf += dF;
      fi = fi * (1 + g) + dI; ci += dI;
      payF += a; payI += b; yF += a; yI += b;
      if (m % 12 === 0) {
        var home = o.home * Math.pow(1 + o.appr / 100, m / 12);
        var nF = home - bf + after(ff, cf), nI = home - bi + after(fi, ci);
        rows.push({ year: m / 12, payF: yF, payI: yI, eqF: home - bf, eqI: home - bi, fundF: after(ff, cf), fundI: after(fi, ci), lead: nI - nF });
        yF = 0; yI = 0;
      }
    }
    var last = rows[rows.length - 1];
    return { pf: pf, ioPay: ioPay, amPay: amPay, bf: bf, bi: bi, intF: intF, intI: intI, payF: payF, payI: payI, last: last, rows: rows };
  }

  function breakEven(o) {
    function f(r) { return compare(Object.assign({}, o, { ret: r })).last.lead; }
    var lo = -20, hi = 50, flo = f(lo), fhi = f(hi);
    if (flo === 0) return lo;
    if (flo * fhi > 0) return NaN;
    for (var k = 0; k < 80; k++) {
      var mid = (lo + hi) / 2, fm = f(mid);
      if ((fm > 0) === (fhi > 0)) { hi = mid; fhi = fm; } else { lo = mid; }
    }
    return (lo + hi) / 2;
  }
  // --- end pure ---

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }
  function read(id, blank) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blank;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function cell(row, text) { var td = document.createElement('td'); td.textContent = text; row.appendChild(td); }

  var OUT = ['fviLead', 'fviPayF', 'fviPayIo', 'fviPayAm', 'fviShock', 'fviEqF', 'fviEqI', 'fviFundF', 'fviFundI', 'fviNetF', 'fviNetI',
             'fviIntF', 'fviIntI', 'fviBreak', 'fviVerdict', 'fviHorizonOut'];
  function clearAll() { OUT.forEach(function (id) { setText(id, '–'); }); el('fviSchedule').textContent = ''; }

  function update() {
    var o = { loan: read('fviLoan', NaN), years: parseInt(el('fviTerm').value, 10), rf: read('fviRateF', NaN), rio: read('fviRateIo', NaN),
              ioYears: parseInt(el('fviIoYears').value, 10), home: read('fviHome', NaN), appr: read('fviAppr', 0), ret: read('fviReturn', NaN),
              horizon: read('fviHorizon', NaN), tax: read('fviTax', 0) };
    var msg = '';
    if (isNaN(o.loan) || o.loan <= 0) msg = 'Enter a loan amount greater than $0.';
    else if ([o.rf, o.rio].some(function (v) { return isNaN(v) || v < 0 || v > 30; })) msg = 'Enter interest rates from 0% to 30%.';
    else if (o.ioYears >= o.years) msg = 'The interest-only period must be shorter than the loan term.';
    else if (isNaN(o.home) || o.home < 0) msg = 'Enter the home value (0 or more).';
    else if (isNaN(o.appr) || o.appr < -20 || o.appr > 30) msg = 'Enter a yearly change in home value from -20% to 30%.';
    else if (isNaN(o.ret) || o.ret < -20 || o.ret > 50) msg = 'Enter an investment return from -20% to 50%.';
    else if (isNaN(o.horizon) || o.horizon < 1 || o.horizon > o.years || o.horizon % 1 !== 0) msg = 'Enter whole years to compare, from 1 up to the loan term.';
    else if (isNaN(o.tax) || o.tax < 0 || o.tax > 60) msg = 'Enter a tax rate on gains from 0% to 60%.';
    el('fviError').hidden = !msg;
    el('fviError').textContent = msg;
    if (msg) { clearAll(); return; }

    var r = compare(o), L = r.last;
    var full = compare(Object.assign({}, o, { horizon: o.years }));
    setText('fviHorizonOut', String(o.horizon));
    setText('fviLead', Math.abs(L.lead) < 1 ? 'Level' : (L.lead > 0 ? 'Interest-only by ' : 'Fixed rate by ') + money.format(Math.abs(L.lead)));
    setText('fviPayF', cents.format(r.pf));
    setText('fviPayIo', cents.format(r.ioPay));
    setText('fviPayAm', cents.format(r.amPay));
    setText('fviShock', '+' + cents.format(r.amPay - r.ioPay) + (r.ioPay > 0 ? ' (' + ((r.amPay / r.ioPay - 1) * 100).toFixed(0) + '%)' : ''));
    setText('fviEqF', money.format(L.eqF));
    setText('fviEqI', money.format(L.eqI));
    setText('fviFundF', money.format(L.fundF));
    setText('fviFundI', money.format(L.fundI));
    setText('fviNetF', money.format(L.eqF + L.fundF));
    setText('fviNetI', money.format(L.eqI + L.fundI));
    setText('fviIntF', money.format(r.intF) + ' (' + money.format(full.intF) + ' over the full term)');
    setText('fviIntI', money.format(r.intI) + ' (' + money.format(full.intI) + ' over the full term)');
    var be = breakEven(o);
    setText('fviBreak', isNaN(be) ? 'None between −20% and 50%' : be.toFixed(2) + '% a year');
    var v;
    if (Math.abs(L.lead) < 1) v = 'The two plans finish level after ' + o.horizon + ' years.';
    else if (L.lead > 0) v = 'Investing the interest-only savings leaves you ' + money.format(L.lead) + ' ahead after ' + o.horizon + ' years at a ' + o.ret + '% return, but you would owe ' + money.format(L.eqF - L.eqI) + ' more on the house.' + (isNaN(be) ? '' : ' Below about ' + be.toFixed(2) + '% a year the fixed-rate loan comes out ahead.');
    else v = 'The fixed-rate loan leaves you ' + money.format(-L.lead) + ' ahead after ' + o.horizon + ' years at a ' + o.ret + '% return.' + (isNaN(be) ? '' : ' The investments would need to earn more than about ' + be.toFixed(2) + '% a year for interest-only to win.');
    setText('fviVerdict', v);

    var body = el('fviSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      cell(tr, String(row.year));
      cell(tr, money.format(row.payF));
      cell(tr, money.format(row.payI));
      cell(tr, money.format(row.eqF));
      cell(tr, money.format(row.eqI));
      cell(tr, money.format(row.fundF));
      cell(tr, money.format(row.fundI));
      cell(tr, Math.abs(row.lead) < 1 ? 'Level' : (row.lead > 0 ? 'IO +' : 'Fixed +') + money.format(Math.abs(row.lead)));
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('fviForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
